<?php
declare(strict_types=1);namespace App\Repositories;use PDO;
final readonly class SecurityGroupRepository{public function __construct(private PDO $db){}public function all():array{$groups=$this->db->query("SELECT r.*,COUNT(DISTINCT ur.user_id) members FROM roles r LEFT JOIN user_roles ur ON ur.role_id=r.id GROUP BY r.id ORDER BY r.system_locked DESC,r.name")->fetchAll();$s=$this->db->prepare('SELECT permission_id FROM role_permissions WHERE role_id=? ORDER BY permission_id');foreach($groups as &$g){$s->execute([$g['id']]);$g['permission_ids']=array_map('intval',$s->fetchAll(PDO::FETCH_COLUMN));}return $groups;}public function permissions():array{return $this->db->query('SELECT id,name,slug FROM permissions ORDER BY SUBSTRING_INDEX(slug,\'.\',1),name')->fetchAll();}public function find(int $id):?array{$s=$this->db->prepare('SELECT * FROM roles WHERE id=?');$s->execute([$id]);return $s->fetch()?:null;}}
